#!/usr/bin/env node
/**
 * Generates src/generated/legacy-module-vars.ts from the original.
 *
 * The original's 139 config files hold the numbers the contract forbids
 * changing. Rather than transcribe them, this asks the running original for
 * every module variable after a full module load (see
 * scripts/php-module-vars-reference.php) and writes them out verbatim.
 *
 * The generated file is checked in so the build and the Worker never need
 * the PHP host, but it must only ever be produced by this script: a hand
 * edit is a value change, which is exactly what must not happen.
 *
 * Usage: node scripts/generate-module-vars.mjs [--check]
 *   --check  regenerate into memory and fail if the checked-in file differs,
 *            so CI catches both a stale file and a hand edit.
 */
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "..");
const outputPath = resolve(repoRoot, "src/generated/legacy-module-vars.ts");

const phpBin = process.env.DTS_PHP_BIN ?? resolve(repoRoot, "tools/php-remote");
const referenceScript = resolve(repoRoot, "scripts/php-module-vars-reference.php");
const instanceRoot = process.env.DTS_ORIGINAL_ROOT ?? "/opt/dts-sandbox/parity/instance";

/**
 * Credentials are withheld by the PHP side, which reports what it withheld.
 * Anything withheld that is not on this list is either a new secret (fine,
 * but worth seeing) or game data being silently lost (not fine), so the
 * generator refuses to write rather than quietly emit a thinner table.
 */
const EXPECTED_WITHHELD = new Set([
  "metman.w_pass",
  "metman.w_teamPass",
  "player.pass",
  "player.teamPass",
  "sys.acbra2_pass",
  "sys.authkey",
  "sys.cpass",
  "sys.db",
  "sys.dbcharset",
  "sys.dbhost",
  "sys.dbname",
  "sys.dbpw",
  "sys.dbreport",
  "sys.dbuser",
  "sys.gtablepre",
  "sys.replay_remote_storage_key",
  "sys.replay_remote_storage_sign",
  "sys.server_address",
  "sys.userdb_remote_storage_pass",
  "sys.userdb_remote_storage_sign"
]);

function readOriginal() {
  const stdout = execFileSync(phpBin, [referenceScript], {
    input: JSON.stringify({ root: instanceRoot }),
    maxBuffer: 256 * 1024 * 1024,
    encoding: "utf8"
  });
  return JSON.parse(stdout);
}

/** Renders one encoded value as the TypeScript literal for it. */
function renderValue(value) {
  switch (value.t) {
    case "null":
      return "null";
    case "bool":
      return value.v ? "true" : "false";
    case "int":
      return String(value.v);
    case "float":
      // A non-finite float arrives as a string; Number() restores it.
      return typeof value.v === "string" ? `Number(${JSON.stringify(value.v)})` : String(value.v);
    case "string":
      return JSON.stringify(value.v);
    case "array": {
      const entries = value.v.map(
        ([key, item]) => `[${typeof key === "number" ? key : JSON.stringify(key)}, ${renderValue(item)}]`
      );
      return `a([${entries.join(", ")}])`;
    }
    default:
      // Closures and objects are code; they are ported by hand, and a module
      // that holds one must not silently become null here.
      throw new Error(`cannot represent a ${value.t} as data`);
  }
}

function generate(dump) {
  const unexpected = dump.skipped.filter(name => !EXPECTED_WITHHELD.has(name));
  if (unexpected.length) {
    throw new Error(
      `the original withheld variables this generator does not know about:\n  ${unexpected.join("\n  ")}\n` +
        "Classify each one: a credential belongs in EXPECTED_WITHHELD, and game data " +
        "belongs in the ALLOW list in scripts/php-module-vars-reference.php."
    );
  }

  const modules = Object.entries(dump.modules);
  const variableCount = modules.reduce((total, [, vars]) => total + Object.keys(vars).length, 0);

  const lines = [
    "// GENERATED by scripts/generate-module-vars.mjs. Do not edit by hand.",
    "//",
    "// Every module variable of the original, read out of a full module load",
    "// rather than transcribed, so the values the contract forbids changing",
    "// cannot drift. Regenerate with `npm run generate:module-vars` and verify",
    "// with `npm run generate:module-vars -- --check`.",
    "//",
    `// ${modules.length} modules, ${variableCount} variables.`,
    "//",
    "// Credentials are withheld by the PHP side; the generator fails if anything",
    "// it does not recognise as a credential is withheld, so game data cannot be",
    "// dropped silently.",
    "",
    'import { PhpArray, type PhpValue } from "../legacy/template/values";',
    "",
    "/** Rebuilds a PHP ordered map, preserving key order and key types. */",
    "const a = (entries: [number | string, PhpValue][]): PhpArray => {",
    "  const array = new PhpArray();",
    "  for (const [key, value] of entries) array.set(key, value);",
    "  return array;",
    "};",
    "",
    "export const LEGACY_MODULE_VARS: Record<string, Record<string, PhpValue>> = {"
  ];

  for (const [module, vars] of modules) {
    lines.push(`  ${JSON.stringify(module)}: {`);
    for (const [name, value] of Object.entries(vars)) {
      lines.push(`    ${JSON.stringify(name)}: ${renderValue(value)},`);
    }
    lines.push("  },");
  }

  lines.push("};", "");
  lines.push("export const LEGACY_MODULE_VARS_SUMMARY = {");
  lines.push(`  modules: ${modules.length},`);
  lines.push(`  variables: ${variableCount},`);
  lines.push(`  withheld: ${dump.skipped.length}`);
  lines.push("} as const;", "");
  lines.push("/**");
  lines.push(" * Reads one module variable the way the original's");
  lines.push(" * `eval(import_module('x'))` prologue does.");
  lines.push(" *");
  lines.push(" * Returns null for a name the module does not define, matching PHP's");
  lines.push(" * undefined-variable read rather than throwing.");
  lines.push(" */");
  lines.push("export function legacyModuleVar(module: string, name: string): PhpValue {");
  lines.push("  return LEGACY_MODULE_VARS[module]?.[name] ?? null;");
  lines.push("}");
  lines.push("");

  return lines.join("\n");
}

const generated = generate(readOriginal());

if (process.argv.includes("--check")) {
  const existing = readFileSync(outputPath, "utf8");
  if (existing !== generated) {
    console.error(
      "src/generated/legacy-module-vars.ts does not match the original.\n" +
        "Run `npm run generate:module-vars` and commit the result. If you edited it by " +
        "hand, that is a value change the contract forbids; regenerate instead."
    );
    process.exit(1);
  }
  console.log("module vars match the original");
} else {
  writeFileSync(outputPath, generated);
  console.log(`wrote ${outputPath}`);
}
